Write a REST API endpoint following the pattern shown in these examples. Using Express.js + TypeScript.

Example 1 — GET /api/users:
```typescript
router.get('/api/users', async (req: Request, res: Response) => {
  try {
    const page = parseInt(req.query.page as string) || 1;
    const limit = Math.min(parseInt(req.query.limit as string) || 20, 100);
    const offset = (page - 1) * limit;

    const [users, total] = await Promise.all([
      db.user.findMany({ skip: offset, take: limit, orderBy: { createdAt: 'desc' } }),
      db.user.count(),
    ]);

    res.json({
      data: users,
      pagination: { page, limit, total, pages: Math.ceil(total / limit) },
    });
  } catch (error) {
    console.error('GET /api/users failed:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

Example 2 — POST /api/users:
```typescript
router.post('/api/users', async (req: Request, res: Response) => {
  try {
    const { name, email, role } = req.body;

    if (!name || !email) {
      return res.status(400).json({ error: 'Name and email are required' });
    }

    const existing = await db.user.findUnique({ where: { email } });
    if (existing) {
      return res.status(409).json({ error: 'Email already registered' });
    }

    const user = await db.user.create({
      data: { name, email, role: role || 'member' },
    });

    res.status(201).json({ data: user });
  } catch (error) {
    console.error('POST /api/users failed:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

Example 3 — DELETE /api/users/:id:
```typescript
router.delete('/api/users/:id', async (req: Request, res: Response) => {
  try {
    const { id } = req.params;

    const user = await db.user.findUnique({ where: { id } });
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    if (user.role === 'admin') {
      return res.status(403).json({ error: 'Cannot delete admin users' });
    }

    await db.user.delete({ where: { id } });
    res.status(204).send();
  } catch (error) {
    console.error(`DELETE /api/users/${req.params.id} failed:`, error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

